INSERT INTO `jobs` (`id`, `user_id`, `company_name`, `company_logo`, `title`, `description`, `requirements`, `location`, `job_type`, `salary_min`, `salary_max`, `experience_level`, `application_instructions`, `contact_email`, `contact_phone`, `submitter_name`, `submitter_email`, `submitter_phone`, `views`, `applications`, `approval_status`, `admin_notes`, `is_active`, `created_at`, `updated_at`, `live_in_out`, `background_checked`, `has_car`, `food_cert_required`, `alcohol_tobacco_cert`, `is_featured`, `urgency`) VALUES (5,NULL,'Ahimsa MD',NULL,'House Assistant','Looking for person who can help run, clean and maintain our home. We are two physicians with 2 kids, 6 and 4 years old.\r\n\r\nNeed help with cooking, cleaning, organizing, laundry, ironing, food preparation. Keeping clothes organized in closets, keeping bathrooms clean. Keeping patio clean. Keeping toys stored and neat.\r\nBeing proactive, anticipatory, and kind to children.\r\n\r\nHelp with children will include feeding them, bathing them, and helping with homework when possible. Will have to watch kids after school.','Needs to speak English enough to communicate with kids.\r\n\r\nWe are high functioning, busy household. Needs to keep up with multitasking and pace of work environment','Miami FL','full-time',NULL,NULL,'mid','Drivers license\r\nPassport \r\nFamily history\r\nMental health history \r\nMedications?','simonibaid@gmail.com','3055051762','Simoni','simonibaid@gmail.com','3055051762',1,0,'approved','',0,'2025-05-16 02:49:13','2026-05-05 17:53:53','n/a',0,0,0,0,0,'normal'),(6,NULL,'N/A',NULL,'Nanny','Job Description:\r\nWe are a warm, welcoming family based in Long Island City, Queens, seeking a loving, experienced, and dependable full-time nanny to care for our 3-month-old baby. \r\nOur home is conveniently located just steps from the Vernon Blvd/Jackson Ave 7 train station, perfect for an easy and quick commute. Dad works remotely from a separate home office and will be present but fully respectful of your routine, allowing you to take the lead in all aspects of baby care. Mom is Nepali. \r\n\r\nResponsibilities:\r\n* Provide attentive, nurturing care for our infant, always prioritizing safety and well-being\r\n* Engage in age-appropriate developmental activities (e.g., tummy time, reading, singing, sensory play)\r\n* Follow and support our feeding and sleep schedule; prepare and clean bottles (formula and/or breast milk)\r\n* Handle diaper changes, soothing routines, and occasional infant bath time\r\n* Manage light baby-related housekeeping, including washing bottles and pump parts, doing baby laundry, preparing baby meals, and tidying the nursery/play areas\r\n* Maintain open, proactive communication with parents throughout the day regarding baby’s mood, activities, and needs\r\n\r\nSchedule:\r\n* Monday–Friday, approximately 8:30 AM – 5:30 PM\r\n* Flexibility Required: Occasional paid evening coverage (3-5 times per month), with at minimum 1-month advanced notice provided','Qualifications:\r\n* Minimum 3+ years of professional nanny experience, with strong infant (0–12 months) experience\r\n* Current Infant CPR and First Aid certification\r\n* Excellent, verifiable references from recent nanny positions\r\n* Non-smoker\r\n* Comfortable working in a home with a parent present\r\n* Warm, patient, and proactive approach to childcare','Long Island City, NY','full-time',NULL,NULL,'entry','To Apply:\r\nIf you’re a caring and experienced childcare professional who meets the above qualifications, we’d love to hear from you! Please send the following to johnandutsha@gmail.com:\r\n* Your resume\r\n* A brief introduction\r\n* Contact information for at least two professional references','','','Utsha','johnandutsha@gmail.com','',3,0,'approved','',0,'2025-09-09 00:49:51','2026-05-05 17:53:57','n/a',0,0,0,0,0,'normal'),(7,42,'Home',NULL,'Live in Nanny','Looking for a live in Nepali or Tibetan nanny in Los Angeles area. Legal status. No need for driving. Caring for 3 year old boy. Work 5 days/week. Household cleaning and cooking while child at school. Competitive salary.','Past experience as nanny.','Los Angeles','full-time',NULL,NULL,'senior','Past References to call','vistasix@yahoo.com','','shaka So','vistasix@yahoo.com','',32,0,'approved','',1,'2025-10-26 23:35:37','2026-07-29 02:35:42','n/a',0,0,0,0,0,'normal'),(8,44,'B&amp;H Employment&amp;Consultancy INC',NULL,'Nanny or babysitter','I am a caring and reliable nanny with a strong passion for fostering children’s growth and well-being. I take pride in creating a safe, stimulating, and loving environment where children can learn, play, and enjoy . With experience supporting daily routines and organizing creative activities, I strive to encourage confidence, fun, and joy in every child I care for.','1. Experience: More than 8 years \r\n2.Education: high school diploma from Nepal( Nepal institute of Health Sciences)\r\n3. Education: Biology in New York ( LaGuardia community college) presents','37-51 75th St Jackson Heights','full-time',30.00,45.00,'senior','I’ll send by mail the attachment Pfd.','spema413@gmail.com','6466832015','Pema Sherpa','spema413@gmail.com','6466832015',21,0,'approved','',1,'2025-11-11 16:27:44','2026-07-29 02:35:45','n/a',0,0,0,0,0,'normal'),(10,1,'B&amp;H Employment&amp;Consultancy INC',NULL,'Hiring Live out Nanny $170 per day','Houskeeping cleaning','Hindi language \r\nHouskeeping cleaning','Manhhatan','full-time',170.00,NULL,'entry','','','','Admin User','admin@bh.com','',55,0,'approved','',1,'2025-12-04 23:22:15','2026-07-29 02:35:36','n/a',0,0,0,0,0,'normal'),(19,1,'bh employment','uploads/logos/1778253068_loogo.jpg','Fast food helper','Pay $900 per 6 days a week\r\nLooking for fast food restaurant workers\r\n\r\nAbout:\r\nFast food restaurant \r\nlive in $900/6 days \r\nfood room free\r\nlongisland\r\nRemote: No\r\nCompensation: USD annually','Category: Kitchen Helper\r\nTags: fast food\r\nLanguages: Hindi\r\nDriving License: not_required\r\n\r\nRequirements:','Longisland','full-time',17.00,17.00,'entry','','admin@bh.com','19293856177','Admin User','admin@bh.com','19293856177',61,1,'approved','',1,'2026-05-08 15:11:08','2026-07-29 02:35:39','live-in',0,0,0,0,0,'normal'),(21,1,'bh employment',NULL,'Elderly care live in new jersey','$350 per day\r\nHiring live in job in new jersey\r\nElderly care HHA\n\nAbout:\nContact us for live in job in new jersey elderly care\nRemote: No\nCompensation: USD hourly','Category: Nanny\nTags: elderly care\nLanguages: English\nDriving License: required\n\nRequirements:\nDriving license \r\nUSA green card or citizen','new jersy','full-time',35.00,35.00,'entry','','admin@bh.com','19293856177','Admin User','admin@bh.com','19293856177',42,0,'approved','',1,'2026-05-14 19:01:16','2026-07-29 12:27:16','live-in',0,0,0,0,0,'normal'),(22,1,'bh employment',NULL,'Manhattan Deli Shop Cashier and grill','manhattan Grill, cashier deli\n\nAbout:\nmanhattan Deli guy\nRemote: No\nCompensation: USD hourly','Category: Cashier\nTags: grill, cashier deli\nLanguages: English\nDriving License: not_required\n\nRequirements:\n','Manhattan','full-time',17.00,20.00,'entry','','admin@bh.com','19293856177','Admin User','admin@bh.com','19293856177',36,1,'approved','',1,'2026-05-25 16:27:28','2026-07-29 12:27:22','live-out',0,0,0,0,0,'normal');
